6	/**
7	 * Validates that a telephone number can be converted to E.164 form, mirroring the
8	 * normalization the {@code OwnerMapper} performs on create. The validator does not
9	 * mutate the value, it only checks that a valid E.164 number can be formed from it
10	 * (see {@link E164Telephone}).
11	 */
12	public class TelephoneValidator implements ConstraintValidator<TelephoneValidation, String> {
13	
14	    @Override
